Plan:
Read the Grouping table and build exact-match maps for Main Group and Material rows. For each row in Formula Required, use the Material row when a nonblank Material exists in Grouping; otherwise use the Main Group row. Write the resulting seven age-bucket values as plain numbers into D3:J6.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Formula Required"]
src = vals["Formula Required"]
grp = vals["Grouping"]

def norm(v):
    if v is None:
        return None
    s = str(v).strip()
    return s.lower() if s else None

group_row = {}
material_row = {}

for r in range(2, grp.max_row + 1):
    mg = norm(grp.cell(row=r, column=1).value)
    mat = norm(grp.cell(row=r, column=2).value)

    if mg is not None:
        group_row.setdefault(mg, r)
    if mat is not None:
        material_row.setdefault(mat, r)

for r in range(3, 7):
    mat = norm(src.cell(row=r, column=2).value)
    grp_key = norm(src.cell(row=r, column=3).value)

    use_material = mat is not None and mat in material_row

    for c in range(4, 11):  # D through J
        return_col = c - 1  # Grouping C through I

        if use_material:
            lookup_row = material_row[mat]
        else:
            lookup_row = group_row.get(grp_key)

        if lookup_row is None:
            value = None
        else:
            value = grp.cell(row=lookup_row, column=return_col).value
            if isinstance(value, str):
                try:
                    value = float(value)
                except ValueError:
                    pass

        ws.cell(row=r, column=c).value = value

for r in range(3, 7):
    print(r, [ws.cell(row=r, column=c).value for c in range(4, 11)])

wb.save(OUT)
